// #Medium #Array #2022_03_24_Time_1_ms_(100.00%)_Space_44_MB_(92.64%)
public class Solution {
    public int maxDistToClosest(int[] seats) {
        int n = seats.length;
        int maxDist = 0;
        int lastPerson = -1;

        for (int i = 0; i < n; i++) {
            if (seats[i] == 1) {
                if (lastPerson == -1) {
                    maxDist = i;
                } else {
                    maxDist = Math.max(maxDist, (i - lastPerson) / 2);
                }
                lastPerson = i;
            }
        }

        if (seats[n - 1] == 0) {
            maxDist = Math.max(maxDist, n - 1 - lastPerson);
        }

        return maxDist;
    }
}

