public class Solution {
    public double soupServings(int n) {
        if (n >= 400) {
            return 1.0;
        }

        double[][] dp = new double[n + 1][n + 1];

        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= n; j++) {
                if (i == 0 && j == 0) {
                    dp[i][j] = 0.0;
                } else if (i == 0 && j > 0) {
                    dp[i][j] = 0.0;
                } else if (i > 0 && j == 0) {
                    dp[i][j] = 1.0;
                } else {
                    double serve100 = 0.0;
                    if (i >= 100) {
                        serve100 = 0.25 * dp[i - 100][j];
                    } else {
                        serve100 = (double) i / 100 * dp[0][j];
                    }

                    double serve75 = 0.0;
                    if (i >= 75 && j >= 25) {
                        serve75 = 0.25 * dp[i - 75][j - 25];
                    } else if (i >= 75) {
                        serve75 = (double) i / 75 * dp[0][j];
                    } else if (j >= 25) {
                        serve75 = (double) j / 25 * dp[i][0];
                    }

                    double serve50 = 0.0;
                    if (i >= 50 && j >= 50) {
                        serve50 = 0.25 * dp[i - 50][j - 50];
                    } else if (i >= 50) {
                        serve50 = (double) i / 50 * dp[0][j];
                    } else if (j >= 50) {
                        serve50 = (double) j / 50 * dp[i][0];
                    }

                    double serve25 = 0.0;
                    if (i >= 25 && j >= 75) {
                        serve25 = 0.25 * dp[i - 25][j - 75];
                    } else if (i >= 25) {
                        serve25 = (double) i / 25 * dp[0][j];
                    } else if (j >= 75) {
                        serve25 = (double) j / 75 * dp[i][0];
                    }

                    dp[i][j] = serve100 + serve75 + serve50 + serve25;
                }
            }
        }

        return dp[n][n];
    }
}

