// #Medium #Array #Hash_Table #Sorting #Greedy #2022_03_24_Time_19_ms_(96.16%)_Space_43_MB_(93.42%)
import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;
public class Solution {
    public boolean isNStraightHand(int[] hand, int groupSize) {
        if (hand.length % groupSize != 0) {
            return false;
        }
        Arrays.sort(hand);
        Map<Integer, Integer> count = new HashMap<>();
        for (int card : hand) {
            count.put(card, count.getOrDefault(card, 0) + 1);
        }
        for (int card : hand) {
            if (count.getOrDefault(card, 0) > 0) {
                for (int i = 0; i < groupSize; i++) {
                    int currentCard = card + i;
                    if (!count.containsKey(currentCard) || count.get(currentCard) == 0) {
                        return false;
                    }
                    count.put(currentCard, count.get(currentCard) - 1);
                }
            }
        }
        return true;
    }
}

