import java.util.Arrays;

public class Solution {
    public double new21Game(int n, int k, int maxPts) {
        if (k > n) {
            return 1.0;
        }

        double[] dp = new double[n + 1];
        dp[0] = 1.0;

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= maxPts; j++) {
                if (i - j >= 0) {
                    dp[i] += dp[i - j] * (1.0 / maxPts);
                }
            }
        }

        double result = 0.0;
        for (int i = 0; i <= n && i < k; i++) {
            result += dp[i];
        }

        return result;
    }
}

