import java.util.Arrays;

public class Solution {
    private static final int MOD = 1000000007;

    public int profitableSchemes(int n, int minProfit, int[] group, int[] profit) {
        int numCrimes = group.length;
        int[][][] dp = new int[numCrimes + 1][n + 1][minProfit + 1];

        // Base case: No crimes, no members, no profit
        dp[0][0][0] = 1;

        for (int i = 1; i <= numCrimes; i++) {
            for (int j = 0; j <= n; j++) {
                for (int k = 0; k <= minProfit; k++) {
                    // Option 1: Don't include the current crime
                    dp[i][j][k] = dp[i - 1][j][k];

                    // Option 2: Include the current crime if possible
                    if (j >= group[i - 1]) {
                        int newProfit = k - profit[i - 1];
                        if (newProfit >= 0) {
                            dp[i][j][k] = (dp[i][j][k] + dp[i - 1][j - group[i - 1]][newProfit]) % MOD;
                        }
                    }
                }
            }
        }

        int totalSchemes = 0;
        for (int j = 0; j <= n; j++) {
            for (int k = minProfit; k >= 0; k--) {
                totalSchemes = (totalSchemes + dp[numCrimes][j][k]) % MOD;
            }
        }

        return totalSchemes;
    }
}

