public class Solution {
    public int[] numberOfLines(int[] widths, String s) {
        int lines = 1;
        int currentWidth = 0;
        for (char c : s.toCharArray()) {
            int index = c - 'a';
            if (currentWidth + widths[index] <= 100) {
                currentWidth += widths[index];
            } else {
                lines++;
                currentWidth = widths[index];
            }
        }
        return new int[]{lines, currentWidth};
    }
}

