import java.util.HashMap;
import java.util.Map;

public class Solution {
    public String findReplaceString(String s, int[] indices, String[] sources, String[] targets) {
        Map<Integer, Pair> replacementMap = new HashMap<>();
        for (int i = 0; i < indices.length; i++) {
            replacementMap.put(indices[i], new Pair(sources[i], targets[i]));
        }

        StringBuilder result = new StringBuilder();
        int i = 0;
        while (i < s.length()) {
            if (replacementMap.containsKey(i)) {
                Pair pair = replacementMap.get(i);
                String source = pair.source;
                String target = pair.target;
                if (s.substring(i).startsWith(source)) {
                    result.append(target);
                    i += source.length();
                } else {
                    result.append(s.charAt(i));
                    i++;
                }
            } else {
                result.append(s.charAt(i));
                i++;
            }
        }

        return result.toString();
    }

    static class Pair {
        String source;
        String target;

        public Pair(String source, String target) {
            this.source = source;
            this.target = target;
        }
    }
}

