public class Solution {
    public List<String> ambiguousCoordinates(String s) {
        List<String> result = new ArrayList<>();
        int n = s.length();
        for (int i = 1; i < n - 1; i++) {
            List<String> first = parse(s.substring(0, i));
            List<String> second = parse(s.substring(i, n - 1));
            for (String f : first) {
                for (String se : second) {
                    result.add("(" + f + ", " + se + ")");
                }
            }
        }
        return result;
    }

    private List<String> parse(String s) {
        List<String> result = new ArrayList<>();
        if (s.length() == 0) {
            return result;
        }

        for (int i = 1; i <= s.length(); i++) {
            String front = s.substring(0, i);
            if (front.length() > 1 && front.startsWith("0")) {
                continue;
            }

            if (front.contains(".")) {
                String[] parts = front.split("\\.");
                if (parts.length != 2 || parts[0].length() == 0 || parts[1].length() == 0) {
                    continue;
                }
                if (parts[1].length() > 0 && parts[1].endsWith("0")) {
                    continue;
                }
                if (parts[0].length() == 0) {
                    continue;
                }
                result.add(front);
            } else {
                result.add(front);
            }
        }
        return result;
    }
}

