public class Solution {
    public int surfaceArea(int[][] grid) {
        int n = grid.length;
        int surfaceArea = 0;

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] > 0) {
                    int height = grid[i][j];
                    surfaceArea += 2; // Top and bottom faces

                    // Check left
                    if (j == 0 || grid[i][j - 1] == 0) {
                        surfaceArea += height;
                    } else {
                        surfaceArea += Math.max(0, height - grid[i][j - 1]);
                    }

                    // Check right
                    if (j == n - 1 || grid[i][j + 1] == 0) {
                        surfaceArea += height;
                    } else {
                        surfaceArea += Math.max(0, height - grid[i][j + 1]);
                    }

                    // Check up
                    if (i == 0 || grid[i - 1][j] == 0) {
                        surfaceArea += height;
                    } else {
                        surfaceArea += Math.max(0, height - grid[i - 1][j]);
                    }

                    // Check down
                    if (i == n - 1 || grid[i + 1][j] == 0) {
                        surfaceArea += height;
                    } else {
                        surfaceArea += Math.max(0, height - grid[i + 1][j]);
                    }
                }
            }
        }

        return surfaceArea;
    }
}

