import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;

public class Solution {
    public boolean xorGame(int[] nums) {
        int n = nums.length;
        Map<String, Boolean> memo = new HashMap<>();
        return canAliceWin(nums, 0, true, memo);
    }

    private boolean canAliceWin(int[] nums, int turn, boolean aliceTurn, Map<String, Boolean> memo) {
        String key = Arrays.toString(nums) + "|" + aliceTurn;
        if (memo.containsKey(key)) {
            return memo.get(key);
        }

        int xorSum = 0;
        for (int num : nums) {
            xorSum ^= num;
        }

        if (nums.length == 0) {
            return false;
        }

        if (xorSum == 0) {
            return !aliceTurn;
        }

        boolean foundWinningMove = false;
        for (int i = 0; i < nums.length; i++) {
            int[] nextNums = new int[nums.length - 1];
            int k = 0;
            for (int j = 0; j < nums.length; j++) {
                if (i != j) {
                    nextNums[k++] = nums[j];
                }
            }

            if (!canAliceWin(nextNums, turn + 1, !aliceTurn, memo)) {
                foundWinningMove = true;
                break;
            }
        }

        memo.put(key, foundWinningMove);
        return foundWinningMove;
    }
}

