public class Solution {
    public int[][] spiralMatrixIII(int rows, int cols, int rStart, int cStart) {
        int[][] result = new int[rows * cols][2];
        int index = 0;
        result[index][0] = rStart;
        result[index][1] = cStart;
        index++;

        int step = 1;
        int row = rStart;
        int col = cStart;

        while (index < rows * cols) {
            // Move right
            for (int i = 0; i < step; i++) {
                col++;
                if (row >= 0 && row < rows && col >= 0 && col < cols) {
                    result[index][0] = row;
                    result[index][1] = col;
                    index++;
                    if (index == rows * cols) break;
                }
            }
            if (index == rows * cols) break;

            // Move down
            for (int i = 0; i < step; i++) {
                row++;
                if (row >= 0 && row < rows && col >= 0 && col < cols) {
                    result[index][0] = row;
                    result[index][1] = col;
                    index++;
                    if (index == rows * cols) break;
                }
            }
            if (index == rows * cols) break;

            step++;

            // Move left
            for (int i = 0; i < step; i++) {
                col--;
                if (row >= 0 && row < rows && col >= 0 && col < cols) {
                    result[index][0] = row;
                    result[index][1] = col;
                    index++;
                    if (index == rows * cols) break;
                }
            }
            if (index == rows * cols) break;

            // Move up
            for (int i = 0; i < step; i++) {
                row--;
                if (row >= 0 && row < rows && col >= 0 && col < cols) {
                    result[index][0] = row;
                    result[index][1] = col;
                    index++;
                    if (index == rows * cols) break;
                }
            }
            if (index == rows * cols) break;

            step++;
        }

        return result;
    }
}

