import com.github.leetcode.TreeNode;

public class Solution {
    public TreeNode subtreeWithAllDeepest(TreeNode root) {
        int[] depth = new int[1];
        return dfs(root, 0, depth);
    }

    private TreeNode dfs(TreeNode node, int currentDepth, int[] depth) {
        if (node == null) {
            return null;
        }

        TreeNode left = dfs(node.left, currentDepth + 1, depth);
        TreeNode right = dfs(node.right, currentDepth + 1, depth);

        if (left == null && right == null) {
            if (currentDepth > depth[0]) {
                depth[0] = currentDepth;
                return node;
            } else if (currentDepth == depth[0]) {
                return node;
            } else {
                return null;
            }
        } else if (left == null) {
            if (currentDepth + 1 == depth[0]) {
                return node;
            } else {
                return right;
            }
        } else if (right == null) {
            if (currentDepth + 1 == depth[0]) {
                return node;
            } else {
                return left;
            }
        } else {
            if (currentDepth == depth[0]) {
                return node;
            } else {
                TreeNode result = new TreeNode(0);
                result.left = left;
                result.right = right;
                return result;
            }
        }
    }
}

