// #2022_03_24_Time_21_ms_(73.78%)_Space_54.4_MB_(50.10%)
public class Solution {
    public String pushDominoes(String dominoes) {
        int n = dominoes.length();
        int[] forces = new int[n];

        // Calculate forces from left to right
        int force = 0;
        for (int i = 0; i < n; i++) {
            if (dominoes.charAt(i) == 'R') {
                force = n;
            } else if (dominoes.charAt(i) == 'L') {
                force = 0;
            }
            forces[i] += force;
            if (force > 0) {
                force--;
            }
        }

        // Calculate forces from right to left
        force = 0;
        for (int i = n - 1; i >= 0; i--) {
            if (dominoes.charAt(i) == 'L') {
                force = n;
            } else if (dominoes.charAt(i) == 'R') {
                force = 0;
            }
            forces[i] -= force;
            if (force > 0) {
                force--;
            }
        }

        StringBuilder result = new StringBuilder();
        for (int i = 0; i < n; i++) {
            int combinedForce = forces[i];
            if (combinedForce > 0) {
                result.append('R');
            } else if (combinedForce < 0) {
                result.append('L');
            } else {
                if (dominoes.charAt(i) == '.') {
                    result.append('.');
                } else if (dominoes.charAt(i) == 'L') {
                    result.append('L');
                } else {
                    result.append('R');
                }
            }
        }

        return result.toString();
    }
}

