        for (int num : nums) {
            numSet.add(num);
        }

        int components = 0;
        ListNode current = head;
        boolean inComponent = false;

        while (current != null) {
            if (numSet.contains(current.val)) {
                if (!inComponent) {
                    components++;
                    inComponent = true;
                }
            } else {
                inComponent = false;
            }
            current = current.next;
        }

