import java.util.Arrays;

public class Solution {
    public int matrixScore(int[][] grid) {
        int m = grid.length;
        int n = grid[0].length;
        int maxScore = 0;

        // Iterate through all possible combinations of row flips
        for (int i = 0; i < (1 << m); i++) {
            int[][] tempGrid = Arrays.stream(grid).map(int[]::clone).toArray(int[][]::new);

            // Flip rows based on the current combination
            for (int j = 0; j < m; j++) {
                if ((i & (1 << j)) != 0) {
                    for (int k = 0; k < n; k++) {
                        tempGrid[j][k] = 1 - tempGrid[j][k];
                    }
                }
            }

            // Flip columns to maximize the score
            for (int j = 0; j < n; j++) {
                int ones = 0;
                for (int k = 0; k < m; k++) {
                    if (tempGrid[k][j] == 1) {
                        ones++;
                    }
                }
                if (ones < m - ones) {
                    for (int k = 0; k < m; k++) {
                        tempGrid[k][j] = 1 - tempGrid[k][j];
                    }
                }
            }

            // Calculate the score for the current combination
            int currentScore = 0;
            for (int j = 0; j < n; j++) {
                int columnSum = 0;
                for (int k = 0; k < m; k++) {
                    columnSum += tempGrid[k][j] * (1 << (n - 1 - j));
                }
                currentScore += columnSum;
            }

            maxScore = Math.max(maxScore, currentScore);
        }

        return maxScore;
    }
}

