public class Solution {
    public int[] sumOfDistancesInTree(int n, int[][] edges) {
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            adj.add(new ArrayList<>());
        }
        for (int[] edge : edges) {
            adj.get(edge[0]).add(edge[1]);
            adj.get(edge[1]).add(edge[0]);
        }

        int[] distances = new int[n];
        for (int i = 0; i < n; i++) {
            distances[i] = calculateDistance(i, adj, new boolean[n], 0);
        }

        return distances;
    }

    private int calculateDistance(int node, List<List<Integer>> adj, boolean[] visited, int depth) {
        visited[node] = true;
        int sum = 0;
        for (int neighbor : adj.get(node)) {
            if (!visited[neighbor]) {
                sum += calculateDistance(neighbor, adj, visited, depth + 1);
            }
        }
        return sum + depth;
    }
}

