public class Solution {
    public boolean buddyStrings(String s, String goal) {
        if (s.length() != goal.length()) {
            return false;
        }

        if (s.equals(goal)) {
            // Check for duplicate characters in s
            boolean[] seen = new boolean[26];
            for (char c : s.toCharArray()) {
                int index = c - 'a';
                if (seen[index]) {
                    return true;
                }
                seen[index] = true;
            }
            return false;
        }

        int firstDiff = -1;
        int secondDiff = -1;

        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) != goal.charAt(i)) {
                if (firstDiff == -1) {
                    firstDiff = i;
                } else if (secondDiff == -1) {
                    secondDiff = i;
                } else {
                    return false; // More than two differences
                }
            }
        }

        if (firstDiff == -1 || secondDiff == -1) {
            return false; // No differences or only one difference
        }

        return s.charAt(firstDiff) == goal.charAt(secondDiff) &&
               s.charAt(secondDiff) == goal.charAt(firstDiff);
    }
}

