        Map<String, Integer> img1Positions = new HashMap<>();
        Map<String, Integer> img2Positions = new HashMap<>();

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (img1[i][j] == 1) {
                    img1Positions.put(i + "," + j, 1);
                }
                if (img2[i][j] == 1) {
                    img2Positions.put(i + "," + j, 1);
                }
            }
        }

        int maxOverlap = 0;
        for (String pos1 : img1Positions.keySet()) {
            String[] parts1 = pos1.split(",");
            int row1 = Integer.parseInt(parts1[0]);
            int col1 = Integer.parseInt(parts1[1]);

            for (String pos2 : img2Positions.keySet()) {
                String[] parts2 = pos2.split(",");
                int row2 = Integer.parseInt(parts2[0]);
                int col2 = Integer.parseInt(parts2[1]);

                int rowDiff = row1 - row2;
                int colDiff = col1 - col2;

                if (rowDiff == 0 && colDiff == 0) {
                    maxOverlap++;
                }
            }
        }

        int overlap = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (img1[i][j] == 1 && img2[i][j] == 1) {
                    overlap++;
                }
            }
        }

        int max_overlap = 0;
        for (int i = -n + 1; i < n; i++) {
            for (int j = -n + 1; j < n; j++) {
                int currentOverlap = 0;
                for (int x = 0; x < n; x++) {
                    for (int y = 0; y < n; y++) {
                        int newX = x + i;
                        int newY = y + j;

                        if (newX >= 0 && newX < n && newY >= 0 && newY < n &&
                                img1[x][y] == 1 && img2[newX][newY] == 1) {
                            currentOverlap++;
                        }
                    }
                }
                max_overlap = Math.max(max_overlap, currentOverlap);
            }
        }

        return max_overlap;
    }
}

