// Definition for a binary tree node.
public class Solution {
    int val;
    TreeNode left;
    TreeNode right;
    TreeNode(int x) {
        val = x;
    }
}

public class Solution {

    Map<TreeNode, TreeNode> parentMap = new HashMap<>();

    public List<Integer> distanceK(TreeNode root, TreeNode target, int k) {
        // Build parent map
        buildParentMap(root, null);

        List<Integer> result = new ArrayList<>();
        dfs(target, k, new boolean[1001], result); // Assuming max 1000 nodes

        return result;
    }

    private void buildParentMap(TreeNode node, TreeNode parent) {
        if (node == null) {
            return;
        }

        parentMap.put(node, parent);

        buildParentMap(node.left, node);
        buildParentMap(node.right, node);
    }

    private void dfs(TreeNode node, int k, boolean[] visited, List<Integer> result) {
        if (node == null || visited[node.val]) {
            return;
        }

        visited[node.val] = true;

        if (k == 0) {
            result.add(node.val);
            return;
        }

        dfs(node.left, k - 1, visited, result);
        dfs(node.right, k - 1, visited, result);

        TreeNode parent = parentMap.get(node);
        if (parent != null) {
            dfs(parent, k - 1, visited, result);
        }
    }
}

