                int andResult = numArr[i] & numArr[j];

                int orSetBits = 0;
                int tempOr = orResult;
                while (tempOr > 0) {
                    orSetBits += (tempOr & 1);
                    tempOr >>= 1;
                }

                int andSetBits = 0;
