import java.util.Arrays;

public class Solution {
    private static final int MOD = 1000000007;

    public int distinctSequences(int n) {
        if (n == 0) {
            return 1;
        }

        long[][] dp = new long[n + 1][6];
        for (int i = 0; i < 6; i++) {
            dp[1][i] = 1;
        }

        for (int i = 2; i <= n; i++) {
            for (int j = 0; j < 6; j++) {
                for (int k = 0; k < 6; k++) {
                    if (gcd(j + 1, k + 1) == 1) {
                        boolean gapCondition = true;
                        if (k == j) {
                            gapCondition = false;
                        }

                        if (i >= 2 && k == j) {
                            gapCondition = false;
                        }

                        if (gapCondition) {
                            dp[i][j] = (dp[i][j] + dp[i - 1][k]) % MOD;
                        }
                    }
                }
            }
        }

        long total = 0;
        for (int i = 0; i < 6; i++) {
            total = (total + dp[n][i]) % MOD;
        }

        return (int) total;
    }

    private int gcd(int a, int b) {
        if (b == 0) {
            return a;
        }
        return gcd(b, a % b);
    }
}

