public class Solution {
    public int numberOfWays(int startPos, int endPos, int k) {
        int diff = Math.abs(startPos - endPos);
        if (k < diff) {
            return 0;
        }
        if ((k - diff) % 2 != 0) {
            return 0;
        }

        int maxPos = Math.max(k, Math.abs(endPos - startPos));
        long[][] dp = new long[k + 1][2 * maxPos + 1];
        dp[0][startPos + maxPos] = 1;

        int MOD = 1000000007;

        for (int i = 1; i <= k; i++) {
            for (int j = 0; j < 2 * maxPos + 1; j++) {
                if (dp[i - 1][j] > 0) {
                    if (j + 1 < 2 * maxPos + 1) {
                        dp[i][j + 1] = (dp[i][j + 1] + dp[i - 1][j]) % MOD;
                    }
                    if (j - 1 >= 0) {
                        dp[i][j - 1] = (dp[i][j - 1] + dp[i - 1][j]) % MOD;
                    }
                }
            }
        }

        return (int) dp[k][endPos + maxPos];
    }
}

