public class Solution {
    public int infectTree(TreeNode root, int start) {
        if (root == null) {
            return 0;
        }

        Queue<TreeNode> queue = new LinkedList<>();
        Set<TreeNode> infected = new HashSet<>();

        TreeNode startNode = findNode(root, start);
        if (startNode == null) {
            return 0;
        }

        queue.offer(startNode);
        infected.add(startNode);
        int minutes = 0;

        while (!queue.isEmpty()) {
            int size = queue.size();
            for (int i = 0; i < size; i++) {
                TreeNode node = queue.poll();

                if (node.left != null && !infected.contains(node.left)) {
                    queue.offer(node.left);
                    infected.add(node.left);
                }
                if (node.right != null && !infected.contains(node.right)) {
                    queue.offer(node.right);
                    infected.add(node.right);
                }
            }
            if (!queue.isEmpty()) {
                minutes++;
            }
        }

        if (infected.size() != countNodes(root)) {
            return -1;
        }

        return minutes;
    }

    private TreeNode findNode(TreeNode root, int start) {
        if (root == null) {
            return null;
        }
        if (root.val == start) {
            return root;
        }
        TreeNode left = findNode(root.left, start);
        if (left != null) {
            return left;
        }
        return findNode(root.right, start);
    }

    private int countNodes(TreeNode root) {
        if (root == null) {
            return 0;
        }
        return 1 + countNodes(root.left) + countNodes(root.right);
    }
}

