class Solution {
    public int minPathCost(int[][] grid, int[][] moveCost) {
        int m = grid.length;
        int n = grid[0].length;
        int[][] dp = new int[m][n];

        for (int i = 0; i < n; i++) {
            dp[0][i] = grid[0][i];
        }

        for (int i = 1; i < m; i++) {
            for (int j = 0; j < n; j++) {
                int minCost = Integer.MAX_VALUE;
                for (int k = 0; k < n; k++) {
                    if (k >= 0 && k < n && j >= 0 && j < n) {
                        int cost = dp[i - 1][k] + moveCost[i - 1][k * n + j] + grid[i][j];
                        minCost = Math.min(minCost, cost);
                    }
                }
                dp[i][j] = minCost;
            }
        }

        int minCost = Integer.MAX_VALUE;
        for (int j = 0; j < n; j++) {
            minCost = Math.min(minCost, dp[m - 1][j]);
        }

        return minCost;
    }
}

