public class Solution {
    public int maximumRobots(int[] chargeTimes, int[] runningCosts, long budget) {
        int n = chargeTimes.length;
        int left = 0;
        long currentSum = 0;
        int maxCharge = 0;
        int maxRobots = 0;

        for (int right = 0; right < n; right++) {
            currentSum += runningCosts[right];
            maxCharge = Math.max(maxCharge, chargeTimes[right]);

            while (currentSum + maxCharge > budget) {
                currentSum -= runningCosts[left];
                if (chargeTimes[left] == maxCharge) {
                    maxCharge = 0;
                    for (int i = left + 1; i <= right; i++) {
                        maxCharge = Math.max(maxCharge, chargeTimes[i]);
                    }
                }
                left++;
            }

            maxRobots = Math.max(maxRobots, right - left + 1);
        }

        return maxRobots;
    }
}

