import java.util.HashMap;
import java.util.Map;

public class Solution {
    public boolean matchReplacement(String s, String sub, char[][] mappings) {
        int n = s.length();
        int m = sub.length();

        if (m > n) {
            return false;
        }

        Map<Character, Character> mappingMap = new HashMap<>();
        for (char[] mapping : mappings) {
            mappingMap.put(mapping[0], mapping[1]);
        }

        return matchRecursive(s, sub, 0, 0, mappingMap);
    }

    private boolean matchRecursive(String s, String sub, int sIndex, int subIndex, Map<Character, Character> mappingMap) {
        if (subIndex == sub.length()) {
            return true;
        }

        if (sIndex >= s.length()) {
            return false;
        }

        char subChar = sub.charAt(subIndex);
        char sChar = s.charAt(sIndex);

        if (subChar == sChar) {
            return matchRecursive(s, sub, sIndex + 1, subIndex + 1, mappingMap);
        } else {
            if (mappingMap.containsKey(subChar)) {
                char replacement = mappingMap.get(subChar);
                if (replacement == sChar) {
                    return matchRecursive(s, sub, sIndex + 1, subIndex + 1, mappingMap);
                }
            }
            return false;
        }
    }
}

