public class Solution {
    public long minimumReplacement(int[] nums) {
        long ans = 0;
        int n = nums.length;
        int last = nums[n - 1];
        for (int i = n - 2; i >= 0; i--) {
            if (nums[i] > last) {
                int k = (nums[i] + last - 1) / last;
                ans += k - 1;
                last = nums[i] / k;
            } else {
                last = nums[i];
            }
        }
        return ans;
    }
}

