public class Solution {
    public boolean canChange(String start, String target) {
        int n = start.length();
        List<Integer> lPositionsStart = new ArrayList<>();
        List<Integer> rPositionsStart = new ArrayList<>();
        List<Integer> lPositionsTarget = new ArrayList<>();
        List<Integer> rPositionsTarget = new ArrayList<>();

        for (int i = 0; i < n; i++) {
            if (start.charAt(i) == 'L') {
                lPositionsStart.add(i);
            } else if (start.charAt(i) == 'R') {
                rPositionsStart.add(i);
            }
            if (target.charAt(i) == 'L') {
                lPositionsTarget.add(i);
            } else if (target.charAt(i) == 'R') {
                rPositionsTarget.add(i);
            }
        }

        if (lPositionsStart.size() != lPositionsTarget.size() || rPositionsStart.size() != rPositionsTarget.size()) {
            return false;
        }

        int startLIndex = 0;
        int targetLIndex = 0;

        while (startLIndex < lPositionsStart.size()) {
            int startLPos = lPositionsStart.get(startLIndex);
            int targetLPos = lPositionsTarget.get(targetLIndex);

            if (startLPos > targetLPos) {
                return false;
            }

            for (int i = startLPos + 1; i <= targetLPos; i++) {
                if (start.charAt(i) != '_') {
                    return false;
                }
            }

            startLIndex++;
            targetLIndex++;
        }

        int startRIndex = 0;
        int targetRIndex = 0;

        while (startRIndex < rPositionsStart.size()) {
            int startRPos = rPositionsStart.get(startRIndex);
            int targetRPos = rPositionsTarget.get(targetRIndex);

            if (startRPos < targetRPos) {
                return false;
            }

            for (int i = startRPos - 1; i >= targetRPos; i--) {
                if (start.charAt(i) != '_') {
                    return false;
                }
            }

            startRIndex++;
            targetRIndex++;
        }

        return true;
    }
}

