import java.util.LinkedList;
import java.util.Queue;

public class Solution {
    public int peopleAwareOfSecret(int n, int delay, int forget) {
        long MOD = 1000000007;
        long[] dp = new long[n + 1];
        dp[1] = 1;
        Queue<Long> q = new LinkedList<>();
        q.offer(1L);

        long totalKnown = 1;

        for (int i = 2; i <= n; i++) {
            long newPeople = 0;
            long forgetPeople = 0;

            if (!q.isEmpty()) {
                newPeople = q.peek();
            }

            if (i - delay > 0) {
                q.offer(newPeople);
            }

            if (i - forget >= 1) {
                q.poll();
            }

            totalKnown = (totalKnown + newPeople - (i >= forget ? dp[i - forget] : 0) + MOD) % MOD;
            dp[i] = newPeople;
        }

        return (int) totalKnown;
    }
}

