public class Solution {
    public int maximumsSplicedArray(int[] nums1, int[] nums2) {
        int n = nums1.length;
        int sum1 = 0;
        int sum2 = 0;
        for (int i = 0; i < n; i++) {
            sum1 += nums1[i];
            sum2 += nums2[i];
        }

        int maxScore = Math.max(sum1, sum2);

        for (int left = 0; left < n; left++) {
            for (int right = left; right < n; right++) {
                int currentSum1 = sum1;
                int currentSum2 = sum2;

                // Calculate sum of subarray in nums1
                int subarraySum1 = 0;
                for (int i = left; i <= right; i++) {
                    subarraySum1 += nums1[i];
                }

                // Calculate sum of subarray in nums2
                int subarraySum2 = 0;
                for (int i = left; i <= right; i++) {
                    subarraySum2 += nums2[i];
                }

                // Update sums after swap
                currentSum1 -= subarraySum1;
                currentSum1 += subarraySum2;
                currentSum2 -= subarraySum2;
                currentSum2 += subarraySum1;

                maxScore = Math.max(maxScore, Math.max(currentSum1, currentSum2));
            }
        }

        return maxScore;
    }
}

