import com.github.leetcode.ListNode;

public class Solution {
    public int[][] spiralMatrix(int m, int n, ListNode head) {
        int[][] matrix = new int[m][n];
        int row = 0;
        int col = 0;
        int rowStart = 0;
        int rowEnd = m - 1;
        int colStart = 0;
        int colEnd = n - 1;
        int i = 0;

        while (i < m * n && head != null) {
            // Traverse right
            for (int j = colStart; j <= colEnd; j++) {
                matrix[row][j] = head.val;
                head = head.next;
                i++;
                if (i == m * n) break;
            }
            row++;

            // Traverse down
            for (int j = rowStart + 1; j <= rowEnd; j++) {
                matrix[j][colEnd] = head.val;
                head = head.next;
                i++;
                if (i == m * n) break;
            }
            colEnd--;

            // Traverse left
            if (rowStart < rowEnd) {
                for (int j = colEnd; j >= colStart; j--) {
                    matrix[rowEnd][j] = head.val;
                    head = head.next;
                    i++;
                    if (i == m * n) break;
                }
                rowEnd--;
            }

            // Traverse up
            if (colStart < colEnd) {
                for (int j = rowEnd; j >= rowStart + 1; j--) {
                    matrix[j][colStart] = head.val;
                    head = head.next;
                    i++;
                    if (i == m * n) break;
                }
                colStart++;
            }
        }

        return matrix;
    }
}

