public class Solution {
    private static final int MOD = 1000000007;

    public int countPaths(int[][] grid) {
        int m = grid.length;
        int n = grid[0].length;
        int[][] dp = new int[m][n];
        for (int i = 0; i < m; i++) {
            Arrays.fill(dp[i], -1);
        }
        long count = 0;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                count = (count + dfs(grid, i, j, dp)) % MOD;
            }
        }
        return (int) count;
    }

    private long dfs(int[][] grid, int i, int j, int[][] dp) {
        if (dp[i][j] != -1) {
            return dp[i][j];
        }
        int m = grid.length;
        int n = grid[0].length;
        long count = 1;
        int[][] directions = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};
        for (int[] dir : directions) {
            int newI = i + dir[0];
            int newJ = j + dir[1];
            if (newI >= 0 && newI < m && newJ >= 0 && newJ < n && grid[newI][newJ] > grid[i][j]) {
                count = (count + dfs(grid, newI, newJ, dp)) % MOD;
            }
        }
        dp[i][j] = (int) count;
        return count;
    }
}

