        for (int num : nums) {
            minVal = Math.min(minVal, num);
        }

        int minDeletions = Integer.MAX_VALUE;
        for (int i = 0; i < nums.length; i++) {
            int currentMin = Integer.MAX_VALUE;
            int currentDeletions = 0;
            for (int j = 0; j < nums.length; j++) {
                if (nums[j] != -1) {
                    currentMin = Math.min(currentMin, nums[j]);
                }
            }


            int[] tempNums = Arrays.copyOf(nums, nums.length);

            for (int j = 0; j < nums.length; j++) {
                if (nums[j] == minVal) {
                    tempNums[j] = -1;
                    currentDeletions++;
                }
            }


            int newMin = Integer.MAX_VALUE;
            for(int num : tempNums){
                if(num != -1){
                    newMin = Math.min(newMin, num);
                }
            }


            boolean dividesAll = true;
            if(newMin == Integer.MAX_VALUE){
                dividesAll = false;
            } else {
                for (int num : numsDivide) {
                    if (num % newMin != 0) {
                        dividesAll = false;
                        break;
                    }
                }
            }

            if (dividesAll) {
                minDeletions = Math.min(minDeletions, currentDeletions);
            }
        }

        boolean originalDivides = true;
        for (int num : numsDivide) {
            if (num % minVal != 0) {
                originalDivides = false;
                break;
            }
        }

        if(originalDivides){
