import java.util.ArrayList;
import java.util.List;

public class Solution {
    private int totalXor;
    private List<List<Integer>> adj;
    private int n;
    private int[] nums;

    public int minScore(int[] nums, int[][] edges) {
        this.nums = nums;
        n = nums.length;
        adj = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            adj.add(new ArrayList<>());
        }
        for (int[] edge : edges) {
            int u = edge[0];
            int v = edge[1];
            adj.get(u).add(v);
            adj.get(v).add(u);
        }

        int minScore = Integer.MAX_VALUE;
        for (int i = 0; i < edges.length; i++) {
            for (int j = i + 1; j < edges.length; j++) {
                int u1 = edges[i][0];
                int v1 = edges[i][1];
                int u2 = edges[j][0];
                int v2 = edges[j][1];

                List<List<Integer>> tempAdj = new ArrayList<>();
                for (int k = 0; k < n; k++) {
                    tempAdj.add(new ArrayList<>(adj.get(k)));
                }
                tempAdj.get(u1).remove(Integer.valueOf(v1));
                tempAdj.get(v1).remove(Integer.valueOf(u1));
                tempAdj.get(u2).remove(Integer.valueOf(v2));
                tempAdj.get(v2).remove(Integer.valueOf(u2));

                int[] componentXors = getComponentXors(tempAdj);
                if (componentXors != null) {
                    int maxXor = Math.max(componentXors[0], Math.max(componentXors[1], componentXors[2]));
                    int minXor = Math.min(componentXors[0], Math.min(componentXors[1], componentXors[2]));
                    minScore = Math.min(minScore, maxXor - minXor);
                }
            }
        }

        return minScore;
    }

    private int[] getComponentXors(List<List<Integer>> adj) {
        int n = adj.size();
        boolean[] visited = new boolean[n];
        int[] componentXors = new int[3];
        int componentIndex = 0;

        for (int i = 0; i < n; i++) {
            if (!visited[i]) {
                int xor = 0;
                xor = dfs(i, adj, visited, nums);
                componentXors[componentIndex++] = xor;
                if (componentIndex == 3) {
                    break;
                }
            }
        }

        if (componentIndex != 3) {
            return null;
        }

        return componentXors;
    }

    private int dfs(int u, List<List<Integer>> adj, boolean[] visited, int[] nums) {
        visited[u] = true;
        int xor = 0;
        xor ^= nums[u];

        for (int v : adj.get(u)) {
            if (!visited[v]) {
                xor ^= dfs(v, adj, visited, nums);
            }
        }
        return xor;
    }

    public int minimumScore(int[] nums, int[][] edges) {
        return minScore(nums, edges);
    }
}

