import java.util.Arrays;

public class Solution {
    public int maximumGroups(int[] grades) {
        Arrays.sort(grades);
        int n = grades.length;
        long currentSum = 0;
        int currentSize = 0;
        int groupCount = 0;

        for (int i = 0; i < n; i++) {
            currentSum += grades[i];
            currentSize++;

            if (i + 1 < n) {
                long nextSum = currentSum;
                int nextSize = currentSize;
                int j = i + 1;

                while (j < n) {
                    nextSum += grades[j];
                    nextSize++;
                    if (nextSum > currentSum && nextSize > currentSize) {
                        break;
                    }
                    j++;
                }

                if (j < n && nextSum > currentSum && nextSize > currentSize) {
                    groupCount++;
                    currentSum = nextSum;
                    currentSize = nextSize;
                    i = j;
                } else {
                    break;
                }
            } else {
                break;
            }
        }

        return groupCount + 1;
    }
}

