class Solution {
    /**
     * Given a string of English letters s, return the greatest English letter which
     * occurs as both a lowercase and uppercase letter in s. The returned letter
     * should be in uppercase. If no such letter exists, return an empty string.
     * An English letter b is greater than another letter a if b appears after a in
     * the English alphabet.
     *
     * @param s The input string.
     * @return The greatest English letter which occurs as both a lowercase and
     * uppercase letter in s, or an empty string if no such letter exists.
     */
    public String greatestLetter(String s) {
        char greatest = ' ';
        for (char c = 'a'; c <= 'z'; c++) {
            if (s.contains(String.valueOf(c)) && s.contains(String.valueOf(Character.toUpperCase(c)))) {
                if (c > greatest) {
                    greatest = c;
                }
            }
        }
        if (greatest == ' ') {
            return "";
        }
        return String.valueOf(Character.toUpperCase(greatest));
    }
}

