    TreeNode right;

    TreeNode(int val) {
        this.val = val;
    }

    public static TreeNode create(List<Integer> values) {
        if (values == null || values.isEmpty()) {
            return null;
        }
        return createHelper(values, 0);
    }

    private static TreeNode createHelper(List<Integer> values, int index) {
        if (index >= values.size()) {
            return null;
        }

        TreeNode node = new TreeNode(values.get(index));
        node.left = createHelper(values, 2 * index + 1);
        node.right = createHelper(values, 2 * index + 2);
        return node;
    }
}

