import java.util.Arrays;

public class Solution {
    public long minSumSquareDiff(int[] nums1, int[] nums2, int k1, int k2) {
        int n = nums1.length;
        long[][] dp = new long[k1 + 1][k2 + 1];

        for (int i = 0; i <= k1; i++) {
            for (int j = 0; j <= k2; j++) {
                dp[i][j] = Long.MAX_VALUE;
            }
        }

        dp[0][0] = 0;

        for (int i = 0; i < n; i++) {
            long diff = Math.abs((long)nums1[i] - (long)nums2[i]);
            for (int x = 0; x <= k1; x++) {
                for (int y = 0; y <= k2; y++) {
                    if (dp[x][y] != Long.MAX_VALUE) {
                        // Option 1: Don't modify nums1[i] or nums2[i]

                        // Option 2: Modify nums1[i]
                        if (x + 1 <= k1) {
                            long newDiff = Math.max(0, diff - 1);
                            dp[x + 1][y] = Math.min(dp[x + 1][y], dp[x][y] + newDiff * newDiff);
                        }

                        // Option 3: Modify nums2[i]
                        if (y + 1 <= k2) {
                            long newDiff = Math.max(0, diff - 1);
                            dp[x][y + 1] = Math.min(dp[x][y + 1], dp[x][y] + newDiff * newDiff);
                        }
                    }
                }
            }
        }

        long result = Long.MAX_VALUE;
        for (int i = 0; i <= k1; i++) {
            for (int j = 0; j <= k2; j++) {
                long sum = 0;
                for (int l = 0; l < n; l++) {
                    long currentDiff = Math.abs((long)nums1[l] - (long)nums2[l]);
                    sum += currentDiff * currentDiff;
                }

                result = Math.min(result, sum);
            }
        }

        long sum = 0;
        for (int i = 0; i < n; i++) {
            long diff = Math.abs((long)nums1[i] - (long)nums2[i]);
            sum += diff * diff;
        }

        return result;
    }
}

