public class Solution {
    public long makeSimilar(int[] nums, int[] target) {
        List<Integer> diffs = new ArrayList<>();
        for (int i = 0; i < nums.length; i++) {
            diffs.add(nums[i] - target[i]);
        }

        long operations = 0;
        List<Integer> positiveDiffs = new ArrayList<>();
        List<Integer> negativeDiffs = new ArrayList<>();

        for (int diff : diffs) {
            if (diff > 0) {
                positiveDiffs.add(diff);
            } else if (diff < 0) {
                negativeDiffs.add(diff);
            }
        }

        int i = 0;
        int j = 0;

        while (i < positiveDiffs.size() && j < negativeDiffs.size()) {
            int positiveDiff = positiveDiffs.get(i);
            int negativeDiff = Math.abs(negativeDiffs.get(j));

            operations += Math.abs(positiveDiff - negativeDiff);
            i++;
            j++;
        }

        return operations / 2;
    }
}

