public class Solution {
    public int[] treeQueries(TreeNode root, int[] queries) {
        int[] answer = new int[queries.length];
        for (int i = 0; i < queries.length; i++) {
            TreeNode newRoot = removeSubtree(root, queries[i]);
            answer[i] = getHeight(newRoot);
        }
        return answer;
    }

    private TreeNode removeSubtree(TreeNode root, int target) {
        if (root == null) {
            return null;
        }

        if (root.val == target) {
            return null;
        }

        root.left = removeSubtree(root.left, target);
        root.right = removeSubtree(root.right, target);

        return root;
    }

    private int getHeight(TreeNode root) {
        if (root == null) {
            return -1;
        }

        int leftHeight = getHeight(root.left);
        int rightHeight = getHeight(root.right);

        return Math.max(leftHeight, rightHeight) + 1;
    }
}

