import java.util.PriorityQueue;

public class Solution {
    public long totalCost(int[] costs, int k, int candidates) {
        PriorityQueue<Integer> left = new PriorityQueue<>();
        PriorityQueue<Integer> right = new PriorityQueue<>();

        for (int i = 0; i < candidates; i++) {
            left.add(costs[i]);
        }

        for (int i = costs.length - 1; i >= costs.length - candidates; i--) {
            right.add(costs[i]);
        }

        long totalCost = 0;
        int leftIndex = candidates;
        int rightIndex = costs.length - 1 - candidates;

        for (int i = 0; i < k; i++) {
            int leftMin = left.isEmpty() ? Integer.MAX_VALUE : left.peek();
            int rightMin = right.isEmpty() ? Integer.MAX_VALUE : right.peek();

            if (leftMin <= rightMin) {
                totalCost += leftMin;
                left.poll();
                leftIndex++;
                if (leftIndex < costs.length) { // Check bounds BEFORE adding
                    left.add(costs[leftIndex]);
                }
            } else {
                totalCost += rightMin;
                right.poll();
                rightIndex--;
                if (rightIndex >= 0) { // Check bounds BEFORE adding
                    right.add(costs[rightIndex]);
                }
            }
        }

        return totalCost;
    }
}

