public class Solution {
    public int maxStarSum(int[] nodeValues, int[][] edges, int maxNumberOfEdges) {
        if (nodeValues == null || nodeValues.length == 0) {
            return 0;
        }

        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < nodeValues.length; i++) {
            adj.add(new ArrayList<>());
        }
        for (int[] edge : edges) {
            int u = edge[0];
            int v = edge[1];
            adj.get(u).add(v);
            adj.get(v).add(u);
        }

        int maxStarSum = Integer.MIN_VALUE;
        for (int center = 0; center < nodeValues.length; center++) {
            long currentStarSum = nodeValues[center];
            List<Integer> neighbors = adj.get(center);
            neighbors.sort((a, b) -> nodeValues[b] - nodeValues[a]);

            int edgesUsed = 0;
            for (int neighbor : neighbors) {
                if (edgesUsed < maxNumberOfEdges) {
                    currentStarSum += nodeValues[neighbor];
                    edgesUsed++;
                } else {
                    break;
                }
            }
            maxStarSum = Math.max(maxStarSum, (int) currentStarSum);
        }

        return maxStarSum;
    }
}

