import java.util.Arrays;

public class Solution {
    public int maxJump(int[] stones) {
        int n = stones.length;
        int minCost = Integer.MAX_VALUE;

        for (int i = 0; i < (1 << n); i++) {
            int currentCost = 0;
            int currentPosition = stones[0];
            boolean validPath = true;
            boolean[] visited = new boolean[n];
            visited[0] = true;

            // Forward path
            for (int j = 1; j < n; j++) {
                if ((i >> j) % 2 == 1) {
                    if (!visited[j]) {
                        int jumpLength = Math.abs(currentPosition - stones[j]);
                        currentCost = Math.max(currentCost, jumpLength);
                        currentPosition = stones[j];
                        visited[j] = true;
                    } else {
                        validPath = false;
                        break;
                    }
                }
            }

            if (!validPath || currentPosition != stones[n - 1]) {
                continue;
            }

            // Return path
            int returnCost = Integer.MAX_VALUE;
            for (int j = 0; j < n; j++) {
                if (j == n - 1) continue;

                int currentReturnCost = Integer.MAX_VALUE;
                boolean[] returnVisited = Arrays.copyOf(visited, n);

                if(!returnVisited[j]){
                    int jumpLength = Math.abs(currentPosition - stones[j]);
                    currentReturnCost = jumpLength;
                    returnVisited[j] = true;

                    int finalJump = Math.abs(stones[j] - stones[0]);
                    currentReturnCost = Math.max(currentReturnCost, finalJump);
                    returnCost = Math.min(returnCost, currentReturnCost);
                }
            }

            if(returnCost == Integer.MAX_VALUE){
                int finalJump = Math.abs(currentPosition - stones[0]);
                returnCost = finalJump;
            }

            minCost = Math.min(minCost, Math.max(currentCost, returnCost));
        }

        return minCost;
    }
}

