                if (nums[j] > nums[j + 1]) {
                    rightNonDecreasing = false;
                    break;
                }
            }

            if (leftNonIncreasing && rightNonDecreasing) {
                goodIndices.add(i);
            }
        }

        return goodIndices;
    }
}

