import java.util.List;
import java.util.Set;

public class Solution {
    public int mostProfitablePath(int[][] edges, int bob, int[] amount) {
        int n = amount.length;
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            adj.add(new ArrayList<>());
        }
        for (int[] edge : edges) {
            int u = edge[0];
            int v = edge[1];
            adj.get(u).add(v);
            adj.get(v).add(u);
        }

        int maxProfit = Integer.MIN_VALUE;
        for (int leaf : getLeaves(adj)) {
            int profit = dfs(0, leaf, bob, amount, adj, new HashSet<>());
            maxProfit = Math.max(maxProfit, profit);
        }

        return maxProfit;
    }

    private List<Integer> getLeaves(List<List<Integer>> adj) {
        List<Integer> leaves = new ArrayList<>();
        for (int i = 0; i < adj.size(); i++) {
            if (adj.get(i).size() == 1) {
                leaves.add(i);
            }
        }
        return leaves;
    }

    private int dfs(int u, int target, int bob, int[] amount, List<List<Integer>> adj, Set<Integer> visited) {
        visited.add(u);
        int profit = amount[u];

        if (u == target) {
            return profit;
        }

        int maxProfit = Integer.MIN_VALUE;
        for (int v : adj.get(u)) {
            if (!visited.contains(v)) {
                int currentProfit = dfs(v, target, bob, amount, adj, new HashSet<>(visited));
                if (currentProfit != Integer.MIN_VALUE) {
                    maxProfit = Math.max(maxProfit, currentProfit);
                }
            }
        }

        if (maxProfit == Integer.MIN_VALUE) {
            return Integer.MIN_VALUE;
        }

        if (u == bob) {
            profit /= 2;
        }

        return profit + maxProfit;
    }
}

