public class Solution {
    public long minCost(int[] nums, int[] cost) {
        int n = nums.length;
        long low = Arrays.stream(nums).min().orElse(0);
        long high = Arrays.stream(nums).max().orElse(0);

        long minCost = Long.MAX_VALUE;

        while (low <= high) {
            long mid = low + (high - low) / 2;
            long currentCost = 0;
            for (int i = 0; i < n; i++) {
                currentCost += (long) Math.abs(nums[i] - mid) * cost[i];
            }

            minCost = Math.min(minCost, currentCost);

            long costSum = 0;
            for (int i = 0; i < n; i++) {
                if (nums[i] < mid) {
                    costSum += cost[i];
                }
            }

            if (costSum < (long)n / 2) {
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }

        return minCost;
    }
}

