public class Solution {
    public long makeIntegerBeautiful(long n, int target) {
        long sum = 0;
        long temp = n;
        while (temp > 0) {
            sum += temp % 10;
            temp /= 10;
        }

        if (sum <= target) {
            return 0;
        }

        long x = 0;
        long powerOfTen = 1;

        while (sum > target) {
            int diff = (int)(sum - target);
            int digit = Math.min(9, diff);

            x += digit * powerOfTen;
            sum -= digit;
            powerOfTen *= 10;
        }

        return x;
    }
