import java.util.Arrays;
import java.util.PriorityQueue;

public class Solution {
    public int mostBooked(int n, int[][] meetings) {
        Arrays.sort(meetings, (a, b) -> a[0] - b[0]);

        PriorityQueue<int[]> availableRooms = new PriorityQueue<>((a, b) -> a[0] - b[0]);
        for (int i = 0; i < n; i++) {
            availableRooms.offer(new int[]{0, i}); // {end_time, room_number}
        }

        int[] roomCounts = new int[n];
        PriorityQueue<int[]> busyRooms = new PriorityQueue<>((a, b) -> a[0] - b[0]); // {end_time, room_number}

        for (int[] meeting : meetings) {
            int start = meeting[0];
            int end = meeting[1];

            // Check for available rooms
            while (!busyRooms.isEmpty() && busyRooms.peek()[0] <= start) {
                int[] room = busyRooms.poll();
                availableRooms.offer(room);
            }

            if (availableRooms.isEmpty()) {
                // No available rooms, wait for the next room to become free
                int[] room = busyRooms.poll();
                availableRooms.offer(room);
            }

            int[] room = availableRooms.poll();
            roomCounts[room[1]]++;
            busyRooms.offer(new int[]{end, room[1]});
        }

        int maxMeetings = 0;
        int mostBookedRoom = 0;
        for (int i = 0; i < n; i++) {
            if (roomCounts[i] > maxMeetings) {
                maxMeetings = roomCounts[i];
                mostBookedRoom = i;
            } else if (roomCounts[i] == maxMeetings && i < mostBookedRoom) {
                mostBookedRoom = i;
            }
        }

        return mostBookedRoom;
    }
}

