            int end = Math.min(start + limit - 9, n);
            if (end <= start) {
                return new String[0];
            }
            String part = message.substring(start, end);
            result[i] = String.format("%d/%d", i + 1, parts) + part;
            start = end;
        }

        String reconstructed = "";
        for (String part : result) {
            reconstructed += part.substring(9);
        }

        if (!reconstructed.equals(message)) {
            return new String[0];
        }

        return result;
    }
}

