import java.util.ArrayList;
import java.util.List;

public class Solution {
    public long minimumTotalCost(int[] nums1, int[] nums2) {
        int n = nums1.length;
        List<Integer> sameIndices = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            if (nums1[i] == nums2[i]) {
                sameIndices.add(i);
            }
        }

        int size = sameIndices.size();
        if (size == 0) {
            return 0;
        }

        if (size == 1) {
            return -1;
        }

        long minCost = Long.MAX_VALUE;

        if (size == 2) {
            minCost = (long)sameIndices.get(0) + sameIndices.get(1);
        } else {

            for (int i = 0; i < (1 << size); i++) {
                if (Integer.bitCount(i) != size / 2) continue;

                List<Integer> group1 = new ArrayList<>();
                List<Integer> group2 = new ArrayList<>();

                for (int j = 0; j < size; j++) {
                    if ((i >> j) % 2 == 0) {
                        group1.add(sameIndices.get(j));
                    } else {
                        group2.add(sameIndices.get(j));
                    }
                }

                long currentCost = 0;
                for (int j = 0; j < group1.size(); j++) {
                    currentCost += (long)group1.get(j) + group2.get(j);
                }
                minCost = Math.min(minCost, currentCost);
            }
        }

        if (minCost == Long.MAX_VALUE) {
            return -1;
        }

        return minCost;
    }
}

