import java.util.Arrays;

public class Solution {
    private int[][] grid;
    private int m;
    private int n;

    public int getMaxGridHappiness(int m, int n, int introvertsCount, int extrovertsCount) {
        this.m = m;
        this.n = n;
        this.grid = new int[m][n];
        for (int i = 0; i < m; i++) {
            Arrays.fill(grid[i], 0); // 0: empty, 1: introvert, 2: extrovert
        }
        return solve(0, introvertsCount, extrovertsCount, 0);
    }

    private int solve(int cell, int introvertsCount, int extrovertsCount, int currentHappiness) {
        if (cell == m * n) {
            return currentHappiness;
        }

        int row = cell / n;
        int col = cell % n;

        // Option 1: Don't place anyone in this cell
        int maxHappiness = solve(cell + 1, introvertsCount, extrovertsCount, currentHappiness);

        // Option 2: Place an introvert in this cell
        if (introvertsCount > 0) {
            grid[row][col] = 1;
            int happiness = 120;
            int neighbors = 0;
            neighbors += getNeighborHappiness(row - 1, col, 1);
            neighbors += getNeighborHappiness(row + 1, col, 1);
            neighbors += getNeighborHappiness(row, col - 1, 1);
            neighbors += getNeighborHappiness(row, col + 1, 1);
            happiness -= neighbors * 30;
            int nextHappiness = solve(cell + 1, introvertsCount - 1, extrovertsCount, currentHappiness + happiness);
            maxHappiness = Math.max(maxHappiness, nextHappiness);
            grid[row][col] = 0; // Backtrack
        }

        // Option 3: Place an extrovert in this cell
        if (extrovertsCount > 0) {
            grid[row][col] = 2;
            int happiness = 40;
            int neighbors = 0;
            neighbors += getNeighborHappiness(row - 1, col, 2);
            neighbors += getNeighborHappiness(row + 1, col, 2);
            neighbors += getNeighborHappiness(row, col - 1, 2);
            neighbors += getNeighborHappiness(row, col + 1, 2);
            happiness += neighbors * 20;
            int nextHappiness = solve(cell + 1, introvertsCount, extrovertsCount - 1, currentHappiness + happiness);
            maxHappiness = Math.max(maxHappiness, nextHappiness);
            grid[row][col] = 0; // Backtrack
        }

        return maxHappiness;
    }

    private int getNeighborHappiness(int row, int col, int personType) {
        if (row < 0 || row >= m || col < 0 || col >= n) {
            return 0;
        }

        int neighborType = grid[row][col];

        if (neighborType == 0) {
            return 0;
        } else if (neighborType == 1) { // Introvert
            if (personType == 1) {
                return -30;
            } else {
                return 20;
            }
        } else { // Extrovert
            if (personType == 1) {
                return -30;
            } else {
                return 20;
            }
        }
    }
}

