import java.util.Arrays;

public class Solution {
    public int minimumIncompatibility(int[] nums, int k) {
        int n = nums.length;
        if (n % k != 0) {
            return -1;
        }
        int subsetSize = n / k;
        Arrays.sort(nums);
        int[][] dp = new int[1 << n][k + 1];
        for (int i = 0; i < (1 << n); i++) {
            Arrays.fill(dp[i], Integer.MAX_VALUE);
        }
        dp[0][0] = 0;

        for (int mask = 0; mask < (1 << n); mask++) {
            for (int i = 0; i <= k; i++) {
                if (dp[mask][i] == Integer.MAX_VALUE) {
                    continue;
                }

                if (i == k) {
                    continue;
                }

                for (int j = 0; j < (1 << n); j++) {
                    if ((mask & j) != 0) {
                        continue;
                    }

                    int subsetSizeCount = 0;
                    int maxVal = Integer.MIN_VALUE;
                    int minVal = Integer.MAX_VALUE;
                    int subsetMask = 0;

                    for (int bit = 0; bit < n; bit++) {
                        if ((j & (1 << bit)) != 0) {
                            subsetSizeCount++;
                            maxVal = Math.max(maxVal, nums[bit]);
                            minVal = Math.min(minVal, nums[bit]);
                            subsetMask |= (1 << bit);
                        }
                    }

                    if (subsetSizeCount == subsetSize) {
                        if (maxVal == minVal) {
                            continue; // Skip invalid subset
                        } else {
                            dp[subsetMask | mask][i + 1] = Math.min(dp[subsetMask | mask][i + 1], dp[mask][i] + (maxVal - minVal));
                        }
                    }
                }
            }
        }

        if (dp[(1 << n) - 1][k] == Integer.MAX_VALUE) {
            return -1;
        }

        return dp[(1 << n) - 1][k];
    }
}

