public class Solution {
    public int createSortedArray(int[] instructions) {
        long cost = 0;
        List<Integer> sorted = new ArrayList<>();
        for (int num : instructions) {
            int left = 0;
            int right = sorted.size();
            while (left < right) {
                int mid = (left + right) / 2;
                if (sorted.get(mid) < num) {
                    left = mid + 1;
                } else {
                    right = mid;
                }
            }
            int minVal = Math.min(left, sorted.size() - left);
            if (left == sorted.size()) {
                minVal = 0;
            }
            cost = (cost + minVal) % 1000000007;
            sorted.add(left, num);
        }
        return (int) cost;
    }
}

