public class Solution {
    public class Solution {
        int val;
        TreeNode left;
        TreeNode right;
        TreeNode() {}
        TreeNode(int val) { this.val = val; }
        TreeNode(int val, TreeNode left, TreeNode right) {
            this.val = val;
            this.left = left;
            this.right = right;
        }
    }

    public boolean isEvenOddTree(TreeNode root) {
        if (root == null) {
            return true;
        }

        List<TreeNode> currentLevel = new ArrayList<>();
        currentLevel.add(root);
        int level = 0;

        while (!currentLevel.isEmpty()) {
            List<TreeNode> nextLevel = new ArrayList<>();
            int prevVal = (level % 2 == 0) ? Integer.MIN_VALUE : Integer.MAX_VALUE;

            for (TreeNode node : currentLevel) {
                if (level % 2 == 0) { // Even level - odd values, increasing order
                    if (node.val % 2 == 0 || node.val <= prevVal) {
                        return false;
                    }
                    prevVal = node.val;
                } else { // Odd level - even values, decreasing order
                    if (node.val % 2 != 1 || node.val >= prevVal) {
                        return false;
                    }
                    prevVal = node.val;
                }

                if (node.left != null) {
                    nextLevel.add(node.left);
                }
                if (node.right != null) {
                    nextLevel.add(node.right);
                }
            }

            currentLevel = nextLevel;
            level++;
        }

        return true;
    }
}

