    public int stoneGameVI(int[] aliceValues, int[] bobValues) {
        int n = aliceValues.length;
        int[][] dp = new int[n + 1][2];

        for (int i = 1; i <= n; i++) {
            int aliceMax = Math.max(aliceValues[i - 1] + (i > 1 ? dp[i - 1][1] : 0), bobValues[i - 1] + (i > 1 ? dp[i - 1][0] : 0));
            int bobMax = Math.max(aliceValues[i - 1] + (i > 1 ? dp[i - 1][0] : 0), bobValues[i - 1] + (i > 1 ? dp[i - 1][1] : 0));

            dp[i][0] = aliceMax;
            dp[i][1] = bobMax;
        }

        if (dp[n][0] > dp[n][1]) {
            return 1;
        } else if (dp[n][1] > dp[n][0]) {
            return -1;
        } else {
            return 0;
        }
    }
