public class Solution {
    /**
     * You are the manager of a basketball team. For the upcoming tournament, you want to choose the team with the highest overall score.
     * The score of the team is the sum of scores of all the players in the team. However, the basketball team is not allowed to have conflicts.
     * A conflict exists if a younger player has a strictly higher score than an older player. A conflict does not occur between players of the same age.
     * Given two lists, scores and ages, where each scores[i] and ages[i] represents the score and age of the <u>i</u><sup>th</sup> player, respectively,
     * return the highest overall score of all possible basketball teams.
     *
     * @param scores The scores of the players.
     * @param ages   The ages of the players.
     * @return The highest overall score of all possible basketball teams.
     */
    public int bestTeamScore(int[] scores, int[] ages) {
        int n = scores.length;
        int maxScore = 0;

        for (int i = 0; i < (1 << n); i++) {
            int currentScore = 0;
            boolean validTeam = true;
            int[] teamScores = new int[n];
            int[] teamAges = new int[n];
            int teamSize = 0;

            for (int j = 0; j < n; j++) {
                if ((i >> j) % 2 == 1) {
                    teamScores[teamSize] = scores[j];
                    teamAges[teamSize] = ages[j];
                    currentScore += scores[j];
                    teamSize++;
                }
            }

            for (int j = 0; j < teamSize; j++) {
                for (int k = j + 1; k < teamSize; k++) {
                    if (teamAges[j] < teamAges[k] && teamScores[j] > teamScores[k]) {
                        validTeam = false;
                        break;
                    }
                    if (teamAges[k] < teamAges[j] && teamScores[k] > teamScores[j]) {
                        validTeam = false;
                        break;
                    }
                }
                if (!validTeam) {
                    break;
                }
            }

            if (validTeam) {
                maxScore = Math.max(maxScore, currentScore);
            }
        }

        return maxScore;
    }
}

