                nameToTimes.put(name, new ArrayList<>());
            }
            nameToTimes.get(name).add(totalMinutes);
        }

        List<String> alertedNames = new ArrayList<>();
        for (String name : nameToTimes.keySet()) {
            List<Integer> times = nameToTimes.get(name);
            Collections.sort(times);
            for (int i = 0; i < times.size(); i++) {
                int currentTime = times.get(i);
                int count = 0;
                for (int j = i; j < times.size(); j++) {
                    int nextTime = times.get(j);
                    if (nextTime - currentTime <= 60) {
                        count++;
                    } else {
                        break;
                    }
                }
                if (count >= 3) {
                    alertedNames.add(name);
                    break;
                }
            }
        }

        Collections.sort(alertedNames);
