import java.util.PriorityQueue;

public class Solution {
    public int maxProfit(int[] inventory, int orders) {
        PriorityQueue<Integer> pq = new PriorityQueue<>((a, b) -> b - a);
        for (int count : inventory) {
            pq.offer(count);
        }

        long profit = 0;
        int mod = 1000000007;

        while (orders > 0) {
            int maxCount = pq.poll();
            if (pq.isEmpty()) {
                int ballsToSell = Math.min(orders, maxCount);
                profit = (profit + (long) ballsToSell * (maxCount + maxCount - ballsToSell + 1) / 2) % mod;
                orders -= ballsToSell;
            } else {
                int nextMaxCount = pq.peek();
                int diff = maxCount - nextMaxCount;
                int ballsToSell = Math.min(orders, diff);

                if (ballsToSell > 0) {
                    long currentProfit = (long) ballsToSell * (maxCount + maxCount - ballsToSell + 1) / 2;
                    profit = (profit + currentProfit) % mod;
                    orders -= ballsToSell;
                    pq.offer(maxCount - ballsToSell);
                } else {
                    long currentProfit = (long) orders * (maxCount - nextMaxCount + 1);
                    profit = (profit + currentProfit) % mod;
                    orders = 0;
                }
            }
        }

        return (int) profit;
    }
}

