import java.util.HashMap;
import java.util.HashSet;

public class Solution {
    public int minStickers(String[] stickers, String target) {
        int n = stickers.length;
        int targetLen = target.length();

        // Calculate character frequencies in the target string
        HashMap<Character, Integer> targetFreq = new HashMap<>();
        for (char c : target.toCharArray()) {
            targetFreq.put(c, targetFreq.getOrDefault(c, 0) + 1);
        }

        int[] dp = new int[1 << targetLen];
        for (int i = 0; i < (1 << targetLen); i++) {
            dp[i] = n + 1;
        }
        dp[0] = 0;

        for (int mask = 0; mask < (1 << targetLen); mask++) {
            if (dp[mask] == n + 1) continue;

            for (int i = 0; i < n; i++) {
                String sticker = stickers[i];
                HashMap<Character, Integer> stickerFreq = new HashMap<>();
                for (char c : sticker.toCharArray()) {
                    stickerFreq.put(c, stickerFreq.getOrDefault(c, 0) + 1);
                }

                int nextMask = mask;

                // Create a copy of targetFreq to simulate sticker usage
                HashMap<Character, Integer> tempTargetFreq = new HashMap<>(targetFreq);

                for (int j = 0; j < targetLen; j++) {
                    char targetChar = target.charAt(j);
                    if ((mask & (1 << j)) == 0 && stickerFreq.containsKey(targetChar) && tempTargetFreq.getOrDefault(targetChar, 0) > 0) {
                        tempTargetFreq.put(targetChar, tempTargetFreq.get(targetChar) - 1);
                        nextMask |= (1 << j);
                    }
                }

                dp[nextMask] = Math.min(dp[nextMask], dp[mask] + 1);
            }
        }

        return dp[(1 << targetLen) - 1] > n ? -1 : dp[(1 << targetLen) - 1];
    }
}

