public class Solution {
    private static final int MOD = 1000000007;

    public int numDecodings(String s) {
        int n = s.length();
        long[] dp = new long[n + 1];
        dp[0] = 1;
        dp[1] = (s.charAt(0) == '*' ? 9 : (s.charAt(0) == '0' ? 0 : 1)) % MOD;

        for (int i = 2; i <= n; i++) {
            char first = s.charAt(i - 1);
            char second = s.charAt(i - 2);

            // Decode single digit
            if (first == '*') {
                dp[i] = (dp[i - 1] * 9) % MOD;
            } else if (first != '0') {
                dp[i] = dp[i - 1];
            }

            // Decode two digits
            if (second == '*') {
                if (first >= '0' && first <= '6') {
                    dp[i] = (dp[i] + dp[i - 2] * 2) % MOD;
                } else if (first == '*') {
                    dp[i] = (dp[i] + dp[i - 2] * 9) % MOD;
                } else {
                    dp[i] = (dp[i] + dp[i - 2]) % MOD;
                }
            } else {
                int twoDigit = Integer.parseInt(String.valueOf(second) + String.valueOf(first));
                if (twoDigit >= 10 && twoDigit <= 26) {
                    dp[i] = (dp[i] + dp[i - 2]) % MOD;
                }
            }
        }

        return (int) dp[n];
    }
}

