import java.util.HashSet;
import java.util.Set;

class Solution {
    public int flipLights(int n, int presses) {
        if (n == 0) {
            return 1;
        }

        int[][] dp = new int[presses + 1][1 << n];
        dp[0][0] = 1;

        for (int i = 1; i <= presses; i++) {
            for (int mask = 0; mask < (1 << n); mask++) {
                // Button 1: Flip all bulbs
                int newMask1 = ((1 << n) - 1) ^ mask;
                dp[i][newMask1] = (dp[i][newMask1] + dp[i - 1][mask]) % 1000000007;

                // Button 2: Flip even bulbs
                int newMask2 = mask;
                for (int j = 1; j < n; j += 2) {
                    newMask2 ^= (1 << j);
                }
                dp[i][newMask2] = (dp[i][newMask2] + dp[i - 1][mask]) % 1000000007;

                // Button 3: Flip odd bulbs
                int newMask3 = mask;
                for (int j = 0; j < n; j += 2) {
                    newMask3 ^= (1 << j);
                }
                dp[i][newMask3] = (dp[i][newMask3] + dp[i - 1][mask]) % 1000000007;

                // Button 4: Flip bulbs j = 3k + 1
                int newMask4 = mask;
                for (int j = 0; j < n; j++) {
                    if ((j + 1) % 3 == 1) {
                        newMask4 ^= (1 << j);
                    }
                }
                dp[i][newMask4] = (dp[i][newMask4] + dp[i - 1][mask]) % 1000000007;
            }
        }

        Set<Integer> uniqueStates = new HashSet<>();
        for (int mask = 0; mask < (1 << n); mask++) {
            if (dp[presses][mask] > 0) {
                uniqueStates.add(mask);
            }
        }

        return uniqueStates.size();
    }
}

