                return "No solution";
            }
        }
    }

    private int[] parseSide(String side) {
        int xCoeff = 0;
        int constant = 0;
        String[] terms = side.split("[+-]");

        int sign = 1;
        if (side.startsWith("-")) {
            sign = -1;
        } else if (side.startsWith("+")) {
            sign = 1;
        }

        for (int i = 0; i < terms.length; i++) {
            String term = terms[i].trim();
            if (term.isEmpty()) continue;

            int coeff;
            if (term.contains("x")) {
                if (term.equals("x")) {
                    coeff = 1;
                } else {
                    coeff = Integer.parseInt(term.substring(0, term.indexOf("x")));
                }
                xCoeff += sign * coeff;
            } else {
                constant += sign * Integer.parseInt(term);
            }

            if (i < terms.length - 1) {
                if (side.charAt(side.indexOf(term) + term.length()) == '+') {
                    sign = 1;
                } else if (side.charAt(side.indexOf(term) + term.length()) == '-') {
                    sign = -1;
                }
            }
        }
        return new int[]{xCoeff, constant};
    }
}

