import java.util.HashMap;
import java.util.Map;

public class Solution {
    public int[] findRedundantDirectedConnection(int[][] edges) {
        int n = edges.length;
        int[] parent = new int[n + 1];
        int[] first = new int[] { -1, -1 };
        int second = -1;

        for (int i = 0; i < n; i++) {
            int u = edges[i][0];
            int v = edges[i][1];
            if (parent[v] == 0) {
                parent[v] = u;
            } else {
                first = new int[] { parent[v], v };
                second = u;
            }
        }

        if (second == -1) {
            // Cycle exists, find the edge in the cycle
            int startNode = -1;
            for (int i = 1; i <= n; i++) {
                if (parent[i] != 0) {
                    startNode = i;
                    break;
                }
            }

            if (startNode == -1) {
                return edges[edges.length - 1];
            }

            for (int i = edges.length - 1; i >= 0; i--) {
                int u = edges[i][0];
                int v = edges[i][1];
                if (u == startNode || v == startNode) {
                    return edges[i];
                }
            }
        } else {
            // Two parents exist, find the edge that causes the second parent
            for (int i = edges.length - 1; i >= 0; i--) {
                if (edges[i][1] == first[1] && edges[i][0] == second) {
                    return edges[i];
                }
            }
        }

        return new int[0]; // Should not reach here
    }
}

