public class Solution {
    public List<Double> averageOfLevels(TreeNode root) {
        List<Double> result = new ArrayList<>();
        if (root == null) {
            return result;
        }

        Map<Integer, List<Double>> levelMap = new HashMap<>();
        dfs(root, 0, levelMap);

        for (int level = 0; level < levelMap.size(); level++) {
            List<Double> values = levelMap.get(level);
            double sum = 0;
            for (double value : values) {
                sum += value;
            }
            result.add(sum / values.size());
        }

        return result;
    }

    private void dfs(TreeNode node, int level, Map<Integer, List<Double>> levelMap) {
        if (node == null) {
            return;
        }

        levelMap.computeIfAbsent(level, k -> new ArrayList<>()).add((double) node.val);

        dfs(node.left, level + 1, levelMap);
        dfs(node.right, level + 1, levelMap);
    }
}

