import java.util.Arrays;

public class Solution {
    public boolean canPartitionKSubsets(int[] nums, int k) {
        int sum = 0;
        for (int num : nums) {
            sum += num;
        }
        if (sum % k != 0) {
            return false;
        }
        int target = sum / k;
        Arrays.sort(nums);
        boolean[] visited = new boolean[nums.length];
        return canPartitionKSubsets(nums, k, 0, 0, visited, target);
    }

    private boolean canPartitionKSubsets(int[] nums, int k, int currentIndex, int currentSum, boolean[] visited, int target) {
        if (k == 1) {
            return true;
        }

        if (currentSum == target) {
            return canPartitionKSubsets(nums, k - 1, 0, 0, visited, target);
        }

        for (int i = currentIndex; i < nums.length; i++) {
            if (!visited[i] && currentSum + nums[i] <= target) {
                visited[i] = true;
                if (canPartitionKSubsets(nums, k, i + 1, currentSum + nums[i], visited, target)) {
                    return true;
                }
                visited[i] = false;
            }
        }

        return false;
    }
}

