import java.util.List;
import java.util.ArrayList;
import java.util.stream.Collectors;

public class Solution {
    public int shoppingOffers(int[] price, int[] needs, int[][] special) {
        int n = price.length;
        int baseCost = calculateCost(needs, price);
        int minCost = baseCost;

        for (int[] offer : special) {
            int[] newNeeds = new int[n];
            boolean valid = true;
            for (int i = 0; i < n; i++) {
                newNeeds[i] = needs[i] - offer[i];
                if (newNeeds[i] < 0) {
                    valid = false;
                    break;
                }
            }

            if (valid) {
                int offerPrice = offer[n];
                int remainingCost = shoppingOffers(price, newNeeds, special);
                minCost = Math.min(minCost, offerPrice + remainingCost);
            }
        }

        return minCost;
    }

    private int calculateCost(int[] needs, int[] price) {
        int cost = 0;
        for (int i = 0; i < needs.length; i++) {
            cost += needs[i] * price[i];
        }
        return cost;
    }
}

