public class Solution {
    private int maxPath = 0;

    public int longestUnivaluePath(TreeNode root) {
        dfs(root);
        return maxPath;
    }

    private int dfs(TreeNode node) {
        if (node == null) {
            return 0;
        }

        int leftLength = dfs(node.left);
        int rightLength = dfs(node.right);

        int currentLength = 0;

        if (node.left != null && node.left.val == node.val) {
            currentLength++;
        }
        if (node.right != null && node.right.val == node.val) {
            currentLength++;
        }

        if (currentLength == 2) {
            maxPath = Math.max(maxPath, leftLength + rightLength + 2);
        } else if (currentLength == 1) {
            maxPath = Math.max(maxPath, Math.max(leftLength, rightLength) + 1);
        } else {
            maxPath = Math.max(maxPath, Math.max(leftLength, rightLength));
        }

        return Math.max(leftLength, rightLength) + (currentLength > 0 ? 1 : 0);
    }
}

