import java.util.Map;
import java.util.SortedSet;
import java.util.TreeSet;
public class Solution {
    public List<String> topKFrequent(String[] words, int k) {
        Map<String, Integer> wordCounts = new HashMap<>();
        for (String word : words) {
            wordCounts.put(word, wordCounts.getOrDefault(word, 0) + 1);
        }

        SortedSet<String> sortedWords = new TreeSet<>((a, b) -> {
            int freqA = wordCounts.get(a);
            int freqB = wordCounts.get(b);
            if (freqA != freqB) {
                return freqB - freqA; // Sort by frequency descending
            } else {
                return a.compareTo(b); // Sort lexicographically ascending
            }
        });

        sortedWords.addAll(wordCounts.keySet());

        List<String> result = new ArrayList<>();
        Iterator<String> iterator = sortedWords.iterator();
        for (int i = 0; i < k && iterator.hasNext(); i++) {
            result.add(iterator.next());
        }

        return result;
    }
}

