public class Solution {
    public int[] constructArray(int n, int k) {
        int[] result = new int[n];
        int left = 1;
        int right = n;
        int index = 0;

        if (k == 0) {
            for (int i = 1; i <= n; i++) {
                result[i - 1] = i;
            }
            return result;
        }

        if (k == 1) {
            for (int i = 1; i <= n; i++) {
                result[i - 1] = i;
            }
            return result;
        }

        while (left <= right) {
            if (k > 0) {
                result[index++] = right;
                right--;
                k--;
                if (left <= right) {
                    result[index++] = left;
                    left++;
                }
            } else {
                for (int i = left; i <= right; i++) {
                    result[index++] = i;
                }
                break;
            }
        }

        if (index < n) {
            for (int i = left; i <= n; i++) {
                result[index++] = i;
            }
        }

        return result;
    }
}

