        // Calculate the maximum gain from the left and right subtrees
        int leftGain = Math.max(maxGainFromSubtree(node.left), 0);
        int rightGain = Math.max(maxGainFromSubtree(node.right), 0);

        // Calculate the price to start a new path at the current node
        int priceNewPath = node.val + leftGain + rightGain;

        // Update the maximum path sum if the current path is greater
        maxSum = Math.max(maxSum, priceNewPath);

        // Return the maximum gain from the current node to its parent
        return node.val + Math.max(leftGain, rightGain);
    }
}

