import java.util.Arrays;

public class Solution {
    public int maximumSum(int[] arr) {
        int n = arr.length;
        int maxSum = Integer.MIN_VALUE;

        // Calculate maximum subarray sum without deletion (Kadane's algorithm)
        int currentMax = 0;
        for (int i = 0; i < n; i++) {
            currentMax += arr[i];
            maxSum = Math.max(maxSum, currentMax);
            if (currentMax < 0) {
                currentMax = 0;
            }
        }

        // Iterate through the array and consider deleting each element
        for (int i = 0; i < n; i++) {
            int sumWithoutElement = 0;
            for (int j = 0; j < n; j++) {
                if (i != j) {
                    sumWithoutElement += arr[j];
                }
            }
            maxSum = Math.max(maxSum, sumWithoutElement);
        }

        //Consider subarrays
        for (int i = 0; i < n; i++) {
            for (int j = i; j < n; j++) {
                int currentSum = 0;
                for (int k = i; k <= j; k++) {
                    currentSum += arr[k];
                }

                //Try deleting each element in the subarray
                for (int l = i; l <= j; l++) {
                    int sumWithoutElement = 0;
                    for (int m = i; m <= j; m++) {
                        if (m != l) {
                            sumWithoutElement += arr[m];
                        }
                    }
                    maxSum = Math.max(maxSum, sumWithoutElement);
                }
                maxSum = Math.max(maxSum, currentSum);
            }
        }

        return maxSum;
    }
}

