public class Solution {

    public int maxRepOpt1(String text) {
        return longestRepeatingSubstringAfterOneSwap(text);
    }

    public int longestRepeatingSubstringAfterOneSwap(String text) {
        int n = text.length();
        int maxLen = 0;

        // Iterate through all possible swaps
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                // Swap characters at indices i and j
                char[] chars = text.toCharArray();
                char temp = chars[i];
                chars[i] = chars[j];
                chars[j] = temp;
                String swappedText = new String(chars);

                // Calculate the length of the longest repeating substring in the swapped text
                maxLen = Math.max(maxLen, longestRepeatingSubstring(swappedText));
            }
        }

        return maxLen;
    }

    private int longestRepeatingSubstring(String text) {
        int n = text.length();
        int maxLen = 0;

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int len = 0;
                while (i + len < n && j + len < n && text.charAt(i + len) == text.charAt(j + len)) {
                    len++;
                }
                maxLen = Math.max(maxLen, len);
            }
        }

        return maxLen;
    }
}

