public class Solution {
    public List<Boolean> canMakePaliQueries(String s, int[][] queries) {
        List<Boolean> result = new ArrayList<>();
        int n = s.length();
        int[] prefixXor = new int[n + 1];
        for (int i = 0; i < n; i++) {
            prefixXor[i + 1] = prefixXor[i] ^ (1 << (s.charAt(i) - 'a'));
        }

        for (int[] query : queries) {
            int left = query[0];
            int right = query[1];
            int k = query[2];

            int xorVal = prefixXor[right + 1] ^ prefixXor[left];
            int setBits = 0;
            while (xorVal > 0) {
                setBits += xorVal & 1;
                xorVal >>= 1;
            }

            if (setBits / 2 <= k) {
                result.add(true);
            } else {
                result.add(false);
            }
        }

        return result;
    }
}

