import java.util.Arrays;

public class Solution {
    public int movesToMakeZigzag(int[] nums) {
        int n = nums.length;
        if (n <= 2) {
            return 0;
        }

        int moves1 = 0;
        int moves2 = 0;

        // Calculate moves for even-indexed peaks
        for (int i = 0; i < n; i++) {
            int left = (i > 0) ? nums[i - 1] : Integer.MAX_VALUE;
            int right = (i < n - 1) ? nums[i + 1] : Integer.MAX_VALUE;
            int neededValue = Math.min(left, right) + 1;

            if (i % 2 == 0) { // Even index - should be greater
                if (nums[i] >= neededValue) {
                    moves1 += nums[i] - neededValue + 1;
                }
            } else { // Odd index - should be smaller
                if (nums[i] >= neededValue) {
                    moves1 += nums[i] - neededValue + 1;
                }
            }
        }

        // Calculate moves for odd-indexed peaks
        for (int i = 0; i < n; i++) {
            int left = (i > 0) ? nums[i - 1] : Integer.MAX_VALUE;
            int right = (i < n - 1) ? nums[i + 1] : Integer.MAX_VALUE;
            int neededValue = Math.min(left, right) + 1;

            if (i % 2 != 0) { // Odd index - should be greater
                if (nums[i] >= neededValue) {
                    moves2 += nums[i] - neededValue + 1;
                }
            } else { // Even index - should be smaller
                if (nums[i] >= neededValue) {
                    moves2 += nums[i] - neededValue + 1;
                }
            }
        }

        return Math.min(moves1, moves2);
    }
}

