public class Solution {
    public int mctFromLeafValues(int[] arr) {
        int n = arr.length;
        int[][] dp = new int[n][n];
        int[][] maxVal = new int[n][n];

        for (int i = 0; i < n; i++) {
            dp[i][i] = 0;
            maxVal[i][i] = arr[i];
        }

        for (int len = 2; len <= n; len++) {
            for (int i = 0; i <= n - len; i++) {
                int j = i + len - 1;
                dp[i][j] = Integer.MAX_VALUE;
                for (int k = i; k < j; k++) {
                    int leftMax = maxVal[i][k];
                    int rightMax = maxVal[k + 1][j];
                    int cost = dp[i][k] + dp[k + 1][j] + leftMax * rightMax;
                    if (cost < dp[i][j]) {
                        dp[i][j] = cost;
                    }
                }
                maxVal[i][j] = Integer.MIN_VALUE;
                for (int k = i; k <= j; k++) {
                    maxVal[i][j] = Math.max(maxVal[i][j], arr[k]);
                }
            }
        }

        return dp[0][n - 1];
    }
}

