public class Solution {
    public boolean btreeGameWinningMove(TreeNode root, int n, int x) {
        if (n == 1) {
            return false;
        }

        for (int y = 1; y <= n; y++) {
            if (y != x) {
                if (canWin(root, n, x, y)) {
                    return true;
                }
            }
        }

        return false;
    }

    private boolean canWin(TreeNode root, int n, int x, int y) {
        TreeNode rootX = findNode(root, x);
        TreeNode rootY = findNode(root, y);

        if (rootX == null || rootY == null) {
            return false;
        }

        boolean[] visited = new boolean[n + 1];
        int scoreX = countNodes(rootX, visited);

        visited = new boolean[n + 1];
        int scoreY = countNodes(rootY, visited);

        return scoreX < scoreY;
    }

    private TreeNode findNode(TreeNode root, int val) {
        if (root == null) {
            return null;
        }

        if (root.val == val) {
            return root;
        }

        TreeNode left = findNode(root.left, val);
        if (left != null) {
            return left;
        }

        return findNode(root.right, val);
    }

    private int countNodes(TreeNode root, boolean[] visited) {
        if (root == null) {
            return 0;
        }

        visited[root.val] = true;
        int score = 1;

        // Check left child
        if (root.left != null && !visited[root.left.val]) {
            score += countNodes(root.left, visited);
        }

        // Check right child
        if (root.right != null && !visited[root.right.val]) {
            score += countNodes(root.right, visited);
        }

        return score;
    }
}

