public class Solution {
    /**
     * Calculates the maximum number of stones Alice can get in the game.
     *
     * @param piles The array representing the number of stones in each pile.
     * @return The maximum number of stones Alice can get.
     */
    public int stoneGameII(int[] piles) {
        int n = piles.length;
        int[][] dp = new int[n + 1][n + 1];
        int[] sum = new int[n + 1];

        for (int i = 1; i <= n; i++) {
            sum[i] = sum[i - 1] + piles[i - 1];
        }

        for (int i = n; i >= 1; i--) {
            for (int j = 1; j <= i; j++) {
                if (i == j) {
                    dp[i][j] = sum[i];
                } else {
                    int maxVal = 0;
                    for (int x = 1; x <= 2 * j; x++) {
                        if (i - x >= 0) {
                            maxVal = Math.max(maxVal, sum[i] - dp[i - x][Math.min(i - x, j)]);
                        }
                    }
                    dp[i][j] = maxVal;
                }
            }
        }

        return dp[n][1];
    }
}

