import java.util.Stack;

public class Solution {
    public boolean parseBoolExpr(String expression) {
        Stack<Boolean> values = new Stack<>();
        Stack<Character> operators = new Stack<>();

        for (char c : expression.toCharArray()) {
            if (c == 't') {
                values.push(true);
            } else if (c == 'f') {
                values.push(false);
            } else if (c == '!') {
                operators.push(c);
            } else if (c == '&' || c == '|') {
                operators.push(c);
            } else if (c == '(') {
                // Do nothing, just a marker
            } else if (c == ')') {
                boolean result;
                if (operators.peek() == '&') {
                    operators.pop();
                    result = true;
                    while (!values.isEmpty()) {
                        result &= values.pop();
                    }
                    values.push(result);
                } else if (operators.peek() == '|') {
                    operators.pop();
                    result = false;
                    while (!values.isEmpty()) {
                        result |= values.pop();
                    }
                    values.push(result);
                } else if (operators.peek() == '!') {
                    operators.pop();
                    result = !values.pop();
                    values.push(result);
                }
            }
        }

        return values.pop();
    }
}

