import com_github_leetcode.TreeNode;
import java.util.ArrayList;
import java.util.List;

public class Solution {
    public int maxLevelSum(TreeNode root) {
        List<Long> levelSums = new ArrayList<>();
        dfs(root, 1, levelSums);

        int maxLevel = 1;
        long maxSum = Long.MIN_VALUE;

        for (int i = 0; i < levelSums.size(); i++) {
            if (levelSums.get(i) > maxSum) {
                maxSum = levelSums.get(i);
                maxLevel = i + 1;
            }
        }

        return maxLevel;
    }

    private void dfs(TreeNode node, int level, List<Long> levelSums) {
        if (node == null) {
            return;
        }

        if (level > levelSums.size()) {
            levelSums.add((long)node.val);
        } else {
            levelSums.set(level - 1, levelSums.get(level - 1) + node.val);
        }

        dfs(node.left, level + 1, levelSums);
        dfs(node.right, level + 1, levelSums);
    }
}

