import java.util.Map;

public class Solution {

    static class Transaction {
        int time;
        String city;
        int amount;

        public Transaction(int time, String city, int amount) {
            this.time = time;
            this.city = city;
            this.amount = amount;
        }
    }

    public List<String> invalidTransactions(String[] transactions) {
        List<String> invalid = new ArrayList<>();
        Map<String, List<Transaction>> transactionMap = new HashMap<>();

        for (String transactionStr : transactions) {
            String[] parts = transactionStr.split(",");
            String name = parts[0];
            int time = Integer.parseInt(parts[1]);
            int amount = Integer.parseInt(parts[2]);
            String city = parts[3];

            if (amount > 1000) {
                invalid.add(transactionStr);
                continue;
            }

            if (!transactionMap.containsKey(name)) {
                transactionMap.put(name, new ArrayList<>());
            }

            List<Transaction> transactionList = transactionMap.get(name);
            transactionList.add(new Transaction(time, city, amount));

            for (int i = 0; i < transactionList.size() - 1; i++) {
                Transaction prevTransaction = transactionList.get(i);
                if (Math.abs(time - prevTransaction.time) <= 60 && !city.equals(prevTransaction.city)) {
                    invalid.add(transactionStr);
                    break;
                }
            }
        }

        return invalid;
    }
}

