import java.util.LinkedList;
import java.util.List;

public class Solution {
    public List<Integer> pathInZigZagTree(int label) {
        List<Integer> path = new LinkedList<>();
        int level = 0;
        int temp = label;
        while (temp > 0) {
            level++;
            temp /= 2;
        }

        while (level > 0) {
            path.add(0, label);
            if (level % 2 == 0) {
                label = (1 << level) - label;
            } else {
                if (label == 1) {
                    label = 1;
                } else {
                    label /= 2;
                }
            }
            level--;
        }

        return path;
    }
}

