public class Solution {
    public int largest1BorderedSquare(int[][] grid) {
        if (grid == null || grid.length == 0 || grid[0].length == 0) {
            return 0;
        }

        int rows = grid.length;
        int cols = grid[0].length;
        int maxSide = 0;

        for (int side = 1; side <= Math.min(rows, cols); side++) {
            boolean found = false;
            for (int i = 0; i <= rows - side; i++) {
                for (int j = 0; j <= cols - side; j++) {
                    if (isBorderedSquare(grid, i, j, side)) {
                        maxSide = side;
                        found = true;
                        break;
                    }
                }
                if (found) break;
            }
        }

        return maxSide;
    }

    private boolean isBorderedSquare(int[][] grid, int row, int col, int side) {
        // Check border
        for (int i = row; i < row + side; i++) {
            if (grid[i][col] == 0 || grid[i][col + side - 1] == 0) {
                return false;
            }
        }
        for (int j = col; j < col + side; j++) {
            if (grid[row][j] == 0 || grid[row + side - 1][j] == 0) {
                return false;
            }
        }

        // Check all elements within the square
        for (int i = row; i < row + side; i++) {
            for (int j = col; j < col + side; j++) {
                if (grid[i][j] == 0) {
                    return false;
                }
            }
        }

        return true;
    }
}

