public class Solution {
    public String alphabetBoardPath(String target) {
        Map<Character, int[]> charMap = new HashMap<>();
        for (int i = 0; i < 6; i++) {
            for (int j = 0; j < 5; j++) {
                if (i == 5 && j == 5) {
                    charMap.put('z', new int[]{5, 5});
                } else {
                    charMap.put((char) ('a' + i * 5 + j), new int[]{i, j});
                }
            }
        }

        StringBuilder path = new StringBuilder();
        int row = 0;
        int col = 0;

        for (char c : target.toCharArray()) {
            int[] targetPos = charMap.get(c);
            int targetRow = targetPos[0];
            int targetCol = targetPos[1];

            int rowDiff = targetRow - row;
            int colDiff = targetCol - col;


            if (rowDiff > 0) {
                for (int i = 0; i < rowDiff; i++) {
                    path.append('D');
                }
            } else if (rowDiff < 0) {
                for (int i = 0; i < Math.abs(rowDiff); i++) {
                    path.append('U');
                }
            }

            if (colDiff > 0) {
                for (int i = 0; i < colDiff; i++) {
                    path.append('R');
                }
            } else if (colDiff < 0) {
                for (int i = 0; i < Math.abs(colDiff); i++) {
                    path.append('L');
                }
            }

            path.append('!');
            row = targetRow;
            col = targetCol;
        }

        return path.toString();
    }
}

