import java.util.Arrays;

public class Solution {
    public int[] numSmallerByFrequency(String[] queries, String[] words) {
        int[] ans = new int[queries.length];
        int[] wordFreq = new int[words.length];
        for (int i = 0; i < words.length; i++) {
            wordFreq[i] = getFrequency(words[i]);
        }
        Arrays.sort(wordFreq);
        for (int i = 0; i < queries.length; i++) {
            int queryFreq = getFrequency(queries[i]);
            int left = 0;
            int right = words.length - 1;
            int count = 0;
            while (left <= right) {
                int mid = left + (right - left) / 2;
                if (wordFreq[mid] < queryFreq) {
                    count = mid + 1;
                    left = mid + 1;
                } else {
                    right = mid - 1;
                }
            }
            ans[i] = left;
        }
        return ans;
    }

    private int getFrequency(String s) {
        int[] freq = new int[26];
        for (char c : s.toCharArray()) {
            freq[c - 'a']++;
        }
        int minFreq = Integer.MAX_VALUE;
        for (int i = 0; i < 26; i++) {
            if (freq[i] > 0) {
                minFreq = Math.min(minFreq, freq[i]);
            }
        }
        return minFreq;
    }
}

