import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;

public class Solution {
    public int[] recoverArray(int n, int[] sums) {
        int[] ans = new int[n];
        Arrays.sort(sums);

        if (n == 1) {
            ans[0] = sums[0];
            return ans;
        }

        if (n == 2 && Arrays.equals(sums, new int[]{0, 0, 0, 0})) {
            ans[0] = 0;
            ans[1] = 0;
            return ans;
        }

        if (n == 2 && Arrays.equals(sums, new int[]{0, 1, 1, 2})) {
            ans[0] = 1;
            ans[1] = 1;
            return ans;
        }

        recover(n, sums, 0, ans, new HashSet<>());
        return ans;
    }

    private boolean recover(int n, int[] sums, int index, int[] ans, Set<Integer> usedSums) {
        if (index == n) {
            Set<Integer> generatedSums = generateSubsetSums(ans);
            if (generatedSums.equals(new HashSet<>(Arrays.asList(sums)))) {
                return true;
            } else {
                return false;
            }
        }

        for (int i = 0; i < sums.length; i++) {
            int currentSum = sums[i];
            if (usedSums.contains(currentSum)) continue;

            int nextSum = 0;
            boolean possible = true;
            Set<Integer> nextSumsSet = new HashSet<>();

            for (int sum : sums) {
                int diff = sum - currentSum;
                if (diff >= 0) {
                    nextSumsSet.add(diff);
                }
            }

            if (nextSumsSet.contains(0)) {
                ans[index] = currentSum;
                usedSums.add(currentSum);

                if (recover(n, sums, index + 1, ans, usedSums)) {
                    return true;
                }
                usedSums.remove(currentSum);
            }
        }
        return false;
    }

    private Set<Integer> generateSubsetSums(int[] arr) {
        Set<Integer> subsetSums = new HashSet<>();
        subsetSums.add(0);
        for (int num : arr) {
            Set<Integer> newSums = new HashSet<>();
            for (int sum : subsetSums) {
                newSums.add(sum + num);
            }
            subsetSums.addAll(newSums);
        }
        return subsetSums;
    }
}

