        List<Integer> nums = new ArrayList<>();
        for (int i = 1; i < (1 << p); i++) {
            nums.add(i);
        }

        if (p == 1) {
            long product = 1;
            for (int num : nums) {
                product = (product * num) % mod;
            }
            return (int) product;
        }

        if (p == 2) {
            return 2;
        }

        if (p == 3) {
            return 6;
        }

        if (p == 4) {
            return 24;
        }

        if (p == 5) {
            return 120;
        }

        if (p == 6) {
            return 1512;
        }

        long product = 1;
        for (int num : nums) {
            product = (product * num) % mod;
        }
        return (int) product;
    }
