class Solution {
    private static final int MOD = 1000000007;

    public int numberOfUniqueGoodSubsequences(String binary) {
        Set<String> goodSubsequences = new HashSet<>();
        generateSubsequences(binary, 0, "", goodSubsequences);

        return (int) goodSubsequences.size();
    }

    private void generateSubsequences(String binary, int index, String currentSubsequence, Set<String> goodSubsequences) {
        if (index == binary.length()) {
            if (!currentSubsequence.isEmpty()) {
                if (currentSubsequence.equals("0")) {
                    goodSubsequences.add(currentSubsequence);
                } else if (currentSubsequence.charAt(0) != '0') {
                    goodSubsequences.add(currentSubsequence);
                }
            }
            return;
        }

        // Include the current character
        generateSubsequences(binary, index + 1, currentSubsequence + binary.charAt(index), goodSubsequences);

        // Exclude the current character
        generateSubsequences(binary, index + 1, currentSubsequence, goodSubsequences);
    }
}

