// #Medium #Array #Greedy #Matrix #2022_05_21_Time_4_ms_(100.00%)_Space_79.8_MB_(36.28%)
public class Solution {
    public long maxMatrixSum(int[][] matrix) {
        int n = matrix.length;
        long sum = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                sum += Math.abs(matrix[i][j]);
            }
        }

        int negativeCount = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (matrix[i][j] < 0) {
                    negativeCount++;
                }
            }
        }

        if (negativeCount % 2 == 0) {
            return sum;
        } else {
            int minAbs = Integer.MAX_VALUE;
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    minAbs = Math.min(minAbs, Math.abs(matrix[i][j]));
                }
            }
            return sum - 2 * minAbs;
        }
    }
}

