import java.util.Arrays;
public class Solution {
    public int maxCompatibilitySum(int[][] students, int[][] mentors) {
        int n = students.length;
        int[] permutation = new int[n];
        for (int i = 0; i < n; i++) {
            permutation[i] = i;
        }
        int maxScore = 0;

        return permute(students, mentors, permutation, 0, maxScore);
    }

    private int permute(int[][] students, int[][] mentors, int[] permutation, int k, int maxScore) {
        if (k == students.length) {
            int currentScore = 0;
            for (int i = 0; i < students.length; i++) {
                int compatibility = 0;
                for (int j = 0; j < students[i].length; j++) {
                    if (students[i][j] == mentors[permutation[i]][j]) {
                        compatibility++;
                    }
                }
                currentScore += compatibility;
            }
            return Math.max(maxScore, currentScore);
        }

        int currentMaxScore = maxScore;
        for (int i = k; i < students.length; i++) {
            swap(permutation, k, i);
            currentMaxScore = permute(students, mentors, permutation, k + 1, currentMaxScore);
            swap(permutation, k, i);
        }
        return currentMaxScore;
    }

    private void swap(int[] arr, int i, int j) {
        int temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }
}

